export function generateStaticParams(){return subjects.map(s=>({subject:s.slug}))}
export async function generateMetadata({params}:Props):Promise<Metadata>{const {subject}=await params,s=getSubject(subject);if(!s)return{};return{title:`O/L ${s.en} Past Papers with Answers`,description:`Download O/L ${s.en} past papers and official answers in Sinhala, Tamil and English medium. ${s.si} papers by year.`,alternates:{canonical:`/ol/${s.slug}/`},openGraph:{title:`O/L ${s.en} Past Papers & Answers`,description:`Official ${s.en} O/L papers organized by year and medium.`}}}
export default async function SubjectPage({params}:Props){const {subject}=await params,s=getSubject(subject);if(!s)notFound();const list=papers.filter(p=>p.subject===s.slug),years=[...new Set(list.map(p=>p.year))].sort((a,b)=>b-a),paperCount=list.filter(p=>p.paperUrl).length,answerCount=list.filter(p=>p.markingSchemeUrl).length,complete=list.filter(p=>p.paperUrl&&p.markingSchemeUrl).length;const get=(year:number,medium:string)=>list.find(p=>p.year===year&&p.medium===medium);const crumbs={"@context":"https://schema.org","@type":"BreadcrumbList",itemListElement:[{"@type":"ListItem",position:1,name:"Home",item:`${site.url}/`},{"@type":"ListItem",position:2,name:`O/L ${s.en}`,item:`${site.url}/ol/${s.slug}/`}]};const faq={"@context":"https://schema.org","@type":"FAQPage",mainEntity:[{"@type":"Question",name:`O/L ${s.en} past papers කොහෙන්ද ලබාගන්නේ?`,acceptedAnswer:{"@type":"Answer",text:`මෙම පිටුවෙන් Department of Examinations නිල O/L ${s.en} PDF links වසර සහ මාධ්‍ය අනුව ලබාගත හැක.`}},{"@type":"Question",name:`O/L ${s.en} answers තිබේද?`,acceptedAnswer:{"@type":"Answer",text:`Official marking schemes හෝ evaluation reports ${answerCount}ක් දැනට ලබාගත හැක.`}}]};return <><script type="application/ld+json" dangerouslySetInnerHTML={{__html:JSON.stringify(crumbs)}}/><script type="application/ld+json" dangerouslySetInnerHTML={{__html:JSON.stringify(faq)}}/><section className="pageHero"><div className="shell"><nav className="crumbs"><Link href="/">මුල් පිටුව</Link><span>›</span><Link href="/ol-past-papers/">O/L Papers</Link><span>›</span><b>{s.si}</b></nav><span className={`bigMark ${s.color}`}>{s.mark}</span><small>G.C.E. ORDINARY LEVEL</small><h1>O/L {s.si} Past Papers</h1><p>{s.en} නිල පසුගිය ප්‍රශ්න පත්‍ර, marking schemes සහ evaluation reports වසර හා මාධ්‍ය අනුව ලබාගන්න.</p></div></section><section className="shell collection"><div className="answerBox"><b>කෙටි පිළිතුර</b><p>O/L {s.en} සඳහා question papers {paperCount}ක් සහ official answer resources {answerCount}ක් තිබෙනවා. Paper සහ answer දෙකම ඇති complete sets {complete}ක් ලබාගත හැක.</p><span>Official source: Department of Examinations Sri Lanka</span></div><div className="collectionHead"><div><small>YEAR × MEDIUM</small><h2>{s.si} papers සහ answers</h2></div><span>{list.length} resources</span></div>{list.length?<div className="availabilityWrap"><table className="availability"><thead><tr><th>Year</th><th>සිංහල</th><th>English</th><th>தமிழ்</th></tr></thead><tbody>{years.map(year=><tr key={year}><th><Link href={`/ol-past-papers/${year}/`}>{year}</Link></th>{(["sinhala","english","tamil"] as const).map(m=>{const p=get(year,m);return <td key={m}>{p?<Link className={p.paperUrl&&p.markingSchemeUrl?"cellComplete":p.markingSchemeUrl?"cellAnswer":"cellPaper"} href={paperPath(p)}><b>{p.paperUrl&&p.markingSchemeUrl?"Paper + Answers":p.markingSchemeUrl?"Answers":"Paper"}</b><small>{mediumNames[p.medium]}</small></Link>:<span className="unavailable">—</span>}</td>})}</tr>)}</tbody></table></div>:<div className="emptyBox"><h2>Papers තවම නැහැ</h2><p>නිල resources ලැබුණු පසු මෙහි publish කරනු ලැබේ.</p></div>}</section><section className="seoCopy shell"><h2>O/L {s.en} past papers practice කළ යුත්තේ ඇයි?</h2><p>පසුගිය විභාග ප්‍රශ්න පත්‍ර භාවිතයෙන් ප්‍රශ්න රටාව, කාල කළමනාකරණය සහ official marking guidance අනුව පිළිතුරු සකස් කිරීම පුහුණු කළ හැක. මුලින් paper එක නියමිත වේලාව තුළ කර, පසුව marking scheme හෝ evaluation report එකෙන් පිළිතුරු පරීක්ෂා කරන්න.</p><div className="visibleFaq"><h2>නිතර අසන ප්‍රශ්න</h2><details><summary>O/L {s.en} papers නොමිලේද?</summary><p>ඔව්. සියලු links Department of Examinations නිල PDFs වෙත යොමු කරයි.</p></details><details><summary>Answers නැති වසරක් නම්?</summary><p>නිල answer resource එක නිකුත් වී නැත්නම් Paper Only ලෙස පෙන්වනවා. Link එක ලැබුණු පසු එකම page එකට සම්බන්ධ වේ.</p></details></div></section></>}
